//! TS 类型桥接导出（P2-15）。
//!
//! 将 IPC 相关 Rust 类型经 `ts-rs` 的 `TS::export_to_string()` 拼接导出为
//! `src/ipc/types.ts`，前端 `api.ts` 直接导入，避免手动维护 interface 与
//! 后端字段不同步。依赖类型（枚举、DTO）均已列入下方列表，同一文件内
//! 互相引用即自包含，无需跨文件 import。

use ts_rs::TS;

/// 生成 `src/ipc/types.ts` 的内容（含所有 IPC 类型 + 依赖类型）。
pub fn generate_types() -> Result<String, String> {
    fn ts<T: TS + ?Sized + 'static>() -> Result<String, String> {
        T::export_to_string().map_err(|e| format!("ts-rs export failed: {e}"))
    }

    let mut out = String::new();
    out.push_str(
        "// This file was generated by ts-rs (src-tauri/src/bindings.rs). Do not edit manually.\n",
    );

    let types: Vec<String> = vec![
        ts::<rmccc_auth::AuthSession>()?,
        ts::<rmccc_auth::AccountMetadata>()?,
        ts::<rmccc_profile::Profile>()?,
        ts::<rmccc_profile::ModLoaderConfig>()?,
        ts::<rmccc_profile::ResolvedInstanceSettings>()?,
        ts::<rmccc_modloader::ModLoaderType>()?,
        ts::<rmccc_modloader::LoaderVersion>()?,
        ts::<rmccc_mods::ModVersion>()?,
        ts::<rmccc_mods::ModInfo>()?,
        ts::<rmccc_mods::ModSearchResult>()?,
        ts::<rmccc_version::VersionInfo>()?,
        ts::<rmccc_version::ReleaseType>()?,
        ts::<rmccc_config::AppConfig>()?,
        ts::<rmccc_config::LauncherState>()?,
        ts::<rmccc_config::UserSettings>()?,
        ts::<rmccc_error::IpcError>()?,
        ts::<rmccc_error::ErrorCode>()?,
        ts::<crate::commands::settings::JavaInfo>()?,
        ts::<crate::commands::settings::SettingsUpdate>()?,
        ts::<crate::commands::settings::UserSettingsUpdate>()?,
        ts::<crate::commands::settings::LocaleInfo>()?,
        ts::<crate::commands::profile::ProfileUpdateOpts>()?,
        ts::<crate::events::DownloadProgressPayload>()?,
        ts::<crate::commands::instance::InstanceInfo>()?,
        ts::<crate::commands::instance::MissingFileInfo>()?,
        ts::<crate::commands::instance::InstancePaths>()?,
        ts::<crate::commands::mods::ModList>()?,
        // ── Plugin (Phase 2) ──
        ts::<rmccc_core::rmccc_plugin::PluginSummary>()?,
        ts::<rmccc_core::rmccc_plugin::PluginDetail>()?,
        ts::<rmccc_core::rmccc_plugin::PluginDiagnostic>()?,
        ts::<rmccc_core::rmccc_plugin::InstallReport>()?,
        ts::<rmccc_core::rmccc_plugin::DependencyStatus>()?,
        ts::<rmccc_core::rmccc_plugin::CapabilityInfo>()?,
        ts::<rmccc_core::rmccc_plugin::capability::CapabilityRisk>()?,
        ts::<rmccc_core::rmccc_plugin::manager::DiagnosticSeverity>()?,
        ts::<rmccc_core::rmccc_plugin::registry::PluginState>()?,
        ts::<rmccc_core::rmccc_plugin::registry::TrustLevel>()?,
        ts::<rmccc_core::rmccc_plugin::permissions::PermissionGrant>()?,
        ts::<rmccc_core::rmccc_plugin::permissions::GrantSource>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::PluginManifest>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::Publisher>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::Compatibility>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::Entry>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::PermissionRequest>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::Contributes>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::DashboardCard>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::SettingsPage>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::Theme>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::CardSize>()?,
        ts::<rmccc_core::rmccc_plugin::manifest::ExtensionDependency>()?,
        ts::<rmccc_core::rmccc_plugin::PluginConfig>()?,
        ts::<rmccc_core::rmccc_plugin::PluginContributions>()?,
        ts::<rmccc_core::rmccc_plugin::DashboardCardView>()?,
        ts::<rmccc_core::rmccc_plugin::SettingsPageView>()?,
        ts::<rmccc_core::rmccc_plugin::ThemeView>()?,
        ts::<crate::commands::plugin::PluginList>()?,
        ts::<crate::commands::plugin::PluginConfigView>()?,
    ];

    for t in &types {
        out.push('\n');
        out.push_str(t);
        out.push('\n');
    }
    Ok(out)
}

/// 将生成的类型写入 `src/ipc/types.ts`（相对 src-tauri manifest 目录）。
pub fn write_types_file() -> Result<(), String> {
    let content = generate_types()?;
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .ok_or_else(|| "No parent dir for src-tauri".to_string())?
        .join("src/ipc");
    std::fs::create_dir_all(&dir).map_err(|e| format!("create_dir_all failed: {e}"))?;
    let path = dir.join("types.ts");
    std::fs::write(&path, content).map_err(|e| format!("write types.ts failed: {e}"))?;
    tracing::info!(path = %path.display(), "TS bindings exported");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// P2-15：重新生成 types.ts 并校验与仓库内文件一致（保证生成文件最新）。
    /// 运行 `cargo test -p rmccc test_types_binding_up_to_date` 会重写 types.ts；
    /// CI 中该测试若因字段变更失败，提示提交更新后的生成文件。
    #[test]
    fn test_types_binding_up_to_date() {
        // 写盘生成最新内容（保证开发/CI 后文件最新）
        write_types_file().expect("write types.ts");
        let content = generate_types().expect("generate types");
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("parent dir")
            .join("src/ipc");
        let path = dir.join("types.ts");
        let existing = std::fs::read_to_string(&path).expect("read types.ts");
        assert_eq!(
            existing, content,
            "src/ipc/types.ts 过期：字段/类型变更后需重新生成并提交该文件"
        );
    }
}
